-- First official-source batch for Machico. Entries are municipality-directory listings, not independently verified operating-status checks.
on conflict (id) do update set name=excluded.name,category=excluded.category,publisher=excluded.publisher,url=excluded.url,authority=excluded.authority,scope=excluded.scope,update_note=excluded.update_note,last_checked_at=excluded.last_checked_at,is_active=excluded.is_active;

on conflict (external_key) do update set
 name=excluded.name,category=excluded.category,description=excluded.description,
 municipality_id=excluded.municipality_id,parish=excluded.parish,source_id=excluded.source_id,
 source_url=excluded.source_url,verification_status=excluded.verification_status,
 last_verified_at=excluded.last_verified_at,is_active=excluded.is_active,updated_at=now();
